import { useState } from 'react'
import { Helmet } from 'react-helmet-async'
import { useNavigate, useParams } from 'react-router'

import ArrowBackIcon from '@mui/icons-material/ArrowBack'
import {
  Box,
  Button,
  Card,
  Checkbox,
  Chip,
  Container,
  Divider,
  FormControlLabel,
  Stack,
  Switch,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  Tooltip,
  useTheme,
  TableRow,
  type Theme,
  Typography,
  useMediaQuery
} from '@mui/material'

import PageTitleWrapper from 'src/components/PageTitleWrapper'

import {
  useGetMemberRequests,
  useGetMemberRequestEmailSetting,
  useUpdateMemberRequestEmailSetting,
  useReviewMemberRequests
} from 'src/hooks/api/memberRequest'
import useSafeAuthUser from 'src/hooks/useSafeAuthUser'

import PageHeader from '../PageHeader'
import MemberRequestConfirmDialog from './MemberRequestConfirmDialog'

const MemberRequestListPage = () => {
  const { id } = useParams()
  const clubId = Number(id)
  const { userInfo } = useSafeAuthUser()
  const matches = useMediaQuery((theme: Theme) => theme.breakpoints.up('sm'))
  const theme = useTheme()
  const navigate = useNavigate()

  const club = userInfo?.clubs.find(club => club.id === clubId)
  const { data: memberRequests = [] } = useGetMemberRequests(clubId)
  const { data: emailSetting } = useGetMemberRequestEmailSetting(clubId)
  const { mutate: updateEmailSetting } = useUpdateMemberRequestEmailSetting(clubId)
  const { mutate: reviewRequests } = useReviewMemberRequests(clubId)

  const [selectedRequestIds, setSelectedRequestIds] = useState<number[]>([])
  const [isConfirmDialogOpen, setIsConfirmDialogOpen] = useState<boolean>(false)
  const [confirmDialogAction, setConfirmDialogAction] = useState<'accept' | 'reject' | null>(null)
  const [targetRequestIds, setTargetRequestIds] = useState<number[]>([])

  const handleEmailNotificationSwitchChange = (event: React.ChangeEvent<HTMLInputElement>) => {
    updateEmailSetting(event.target.checked)
  }

  const openConfirmDialog = (action: 'accept' | 'reject', requestIds: number[]) => {
    setConfirmDialogAction(action)
    setTargetRequestIds(requestIds)
    setIsConfirmDialogOpen(true)
  }

  const handleConfirmDialogClose = () => {
    setIsConfirmDialogOpen(false)
    setConfirmDialogAction(null)
    setTargetRequestIds([])
  }

  const handleConfirmDialogSubmit = () => {
    const userIds = targetRequestIds.map(id => {
      const request = memberRequests.find(r => r.id === id)
      return request!.userId
    })
    reviewRequests(
      { userIds, accept: confirmDialogAction === 'accept' },
      {
        onSuccess: () => {
          setSelectedRequestIds([])
          handleConfirmDialogClose()
        }
      }
    )
  }

  const handleAcceptButtonClick = (requestIds: number[]) => {
    openConfirmDialog('accept', requestIds)
  }

  const handleRejectButtonClick = (requestIds: number[]) => {
    openConfirmDialog('reject', requestIds)
  }

  const handleSelectAllCheckboxChange = (event: React.ChangeEvent<HTMLInputElement>) => {
    if (event.target.checked) {
      setSelectedRequestIds(memberRequests.map(request => request.id))
    } else {
      setSelectedRequestIds([])
    }
  }

  const handleMemberCheckboxChange = (event: React.ChangeEvent<HTMLInputElement>, id: number) => {
    if (event.target.checked) {
      setSelectedRequestIds(prev => [...prev, id])
    } else {
      setSelectedRequestIds(prev => prev.filter(requestId => requestId !== id))
    }
  }

  const isAllSelected = memberRequests.length > 0 && selectedRequestIds.length === memberRequests.length
  const isIndeterminate = selectedRequestIds.length > 0 && selectedRequestIds.length < memberRequests.length

  const targetMembers = memberRequests.filter(request => targetRequestIds.includes(request.id))

  return (
    <>
      <Helmet>
        <title>{club?.name ?? ''} 회원 인증 신청 목록 - KLUB</title>
      </Helmet>
      <PageTitleWrapper>
        <PageHeader clubName={club?.name ?? ''} />
      </PageTitleWrapper>
      <Container style={{ width: '100%' }} sx={{ px: matches ? 2 : 0 }}>
        <Box display="flex" justifyContent="flex-end" mb={2}>
          <Tooltip
            title={
              <Typography variant="body2">
                알림 받을 이메일은 <b>동아리 설정</b> 탭에서 <br />
                변경할 수 있어요
              </Typography>
            }
            placement="top"
            arrow
          >
            <FormControlLabel
              control={
                <Switch
                  checked={emailSetting?.receiveEmail ?? false}
                  onChange={handleEmailNotificationSwitchChange}
                  color="primary"
                />
              }
              label={
                <Typography variant="body2" color="text.secondary" fontWeight="bold">
                  이메일 알림 수신
                </Typography>
              }
              sx={{ m: 0 }}
            />
          </Tooltip>
        </Box>
        <Card>
          <Box display="flex" alignItems="center" justifyContent="space-between">
            <Box display="flex" alignItems="baseline" flexDirection="row" sx={{ alignItems: 'center' }}>
              <Button
                variant="text"
                onClick={() => {
                  navigate(-1)
                }}
                color="primary"
              >
                <ArrowBackIcon />
              </Button>
              <Box display={'flex'} alignItems={'center'}>
                <Typography variant="h4" paddingY={2}>
                  회원 인증 신청 관리
                </Typography>
              </Box>
            </Box>
            {selectedRequestIds.length > 0 && (
              <Stack direction="row" spacing={1} sx={{ pr: 2 }}>
                <Typography variant="body2" sx={{ alignSelf: 'center', mr: 2 }}>
                  {selectedRequestIds.length}명 선택됨
                </Typography>
                <Button variant="contained" color="primary" onClick={() => handleAcceptButtonClick(selectedRequestIds)}>
                  수락
                </Button>
                <Button variant="outlined" color="error" onClick={() => handleRejectButtonClick(selectedRequestIds)}>
                  거절
                </Button>
              </Stack>
            )}
          </Box>
          <Divider />
          {memberRequests.length === 0 ? (
            <Box p={4} textAlign="center">
              <Typography variant="body1" color="text.secondary">
                현재 회원 인증 신청이 없습니다.
              </Typography>
            </Box>
          ) : (
            <TableContainer>
              <Table>
                <TableHead>
                  <TableRow>
                    <TableCell padding="checkbox">
                      <Checkbox
                        color="primary"
                        indeterminate={isIndeterminate}
                        checked={isAllSelected}
                        onChange={handleSelectAllCheckboxChange}
                      />
                    </TableCell>
                    <TableCell>이름</TableCell>
                    <TableCell>학번</TableCell>
                    <TableCell>신청 등급</TableCell>
                    <TableCell>신청일</TableCell>
                    <TableCell></TableCell>
                  </TableRow>
                </TableHead>
                <TableBody>
                  {memberRequests.filter(req => req.status == 'PENDING').map(request => {
                    const isSelected = selectedRequestIds.includes(request.id)

                    return (
                      <TableRow
                        key={request.id}
                        hover
                        selected={isSelected}
                        sx={{
                          '& .action-buttons': { visibility: 'hidden' },
                          '&:hover .action-buttons': { visibility: 'visible' },
                          '&&:hover': { backgroundColor: theme.colors.primary.lighter }
                        }}
                      >
                        <TableCell padding="checkbox">
                          <Checkbox
                            color="primary"
                            checked={isSelected}
                            onChange={event => handleMemberCheckboxChange(event, request.id)}
                          />
                        </TableCell>
                        <TableCell>{request.name}</TableCell>
                        <TableCell>{request.studentId}</TableCell>
                        <TableCell>
                          <Chip label={request.requestedLevel} size="small" color="primary" variant="outlined" />
                        </TableCell>
                        <TableCell>{new Date(request.createdAt).toLocaleDateString('ko-KR')}</TableCell>
                        <TableCell align="center">
                          <Stack direction="row" spacing={1} justifyContent="center" className="action-buttons">
                            <Button
                              variant="contained"
                              size="small"
                              color="primary"
                              onClick={() => handleAcceptButtonClick([request.id])}
                            >
                              수락
                            </Button>
                            <Button
                              variant="outlined"
                              size="small"
                              color="error"
                              onClick={() => handleRejectButtonClick([request.id])}
                            >
                              거절
                            </Button>
                          </Stack>
                        </TableCell>
                      </TableRow>
                    )
                  })}
                </TableBody>
              </Table>
            </TableContainer>
          )}
        </Card>
      </Container>

      <MemberRequestConfirmDialog
        isOpen={isConfirmDialogOpen}
        onClose={handleConfirmDialogClose}
        onSubmit={handleConfirmDialogSubmit}
        action={confirmDialogAction}
        targetMembers={targetMembers}
      />
    </>
  )
}

export default MemberRequestListPage
