import { Box, Button, Dialog, DialogActions, DialogContent, DialogTitle, Typography } from '@mui/material'

import type { MemberRequest } from 'src/hooks/api/memberRequest'

interface MemberRequestConfirmDialogProps {
  isOpen: boolean
  onClose: () => void
  onSubmit: () => void
  action: 'accept' | 'reject' | null
  targetMembers: MemberRequest[]
}

const MemberRequestConfirmDialog = ({
  isOpen,
  onClose,
  onSubmit,
  action,
  targetMembers
}: MemberRequestConfirmDialogProps) => {
  if (!action) return null
  return (
    <Dialog open={isOpen} onClose={onClose} maxWidth="xs" fullWidth>
      <DialogTitle sx={{ textAlign: 'center' }}>회원 인증 신청 {action === 'accept' ? '수락' : '거절'}</DialogTitle>
      <DialogContent dividers>
        <Box sx={{ bgcolor: 'background.default', p: 2, borderRadius: 1, maxHeight: 300, overflow: 'auto' }}>
          {targetMembers.map(member => (
            <Typography key={member.id} variant="body2" sx={{ py: 0.5 }}>
              • {member.name} ({member.studentId})
            </Typography>
          ))}
        </Box>
      </DialogContent>
      <DialogActions sx={{ px: 3, pb: 3, pt: 1, gap: 1, display: 'flex', justifyContent: 'center' }}>
        <Button onClick={onClose} variant="outlined">
          취소
        </Button>
        <Button onClick={onSubmit} variant="contained" color={action === 'accept' ? 'primary' : 'error'}>
          {action === 'accept' ? '수락' : '거절'}
        </Button>
      </DialogActions>
    </Dialog>
  )
}

export default MemberRequestConfirmDialog
